import numpy as np
from scipy.optimize import minimize

def g(a):
    return (3 + a)**3 * (a - 5)

def objective(a):
    return np.sum(g(a))

def constraint1(a):
    return np.sum(a)

def constraint2(a):
    return np.sum(a**2) - 12

cons = [
    {'type': 'eq', 'fun': constraint1},
    {'type': 'eq', 'fun': constraint2}
]

# Try different starting points
initial_guesses = [
    [1, 1, 1, -3],
    [-1, -1, -1, 3],
    [np.sqrt(3), np.sqrt(3), -np.sqrt(3), -np.sqrt(3)],
    [2, 2, -2, -2],
    [3, 1, -2, -2],
    [0, 0, np.sqrt(6), -np.sqrt(6)],
    [1.5, 1.5, -1.5, -1.5],
    [2.5, 1.5, -2, -2],
    [3, 0, -1.5, -1.5]
]

min_val = float('inf')
for guess in initial_guesses:
    res = minimize(objective, guess, constraints=cons, method='SLSQP')
    if res.success:
        min_val = min(min_val, res.fun)
        print(f"Guess: {guess}, Result: {res.fun}, x: {res.x}")
    else:
        print(f"Guess: {guess}, Failed")

print(f"Minimum found: {min_val}")

import numpy as np

def get_info(e3):
    # Solve 4t^3 - 12t - e3 = 0
    roots = np.roots([4, 0, -12, -e3])
    ks = 3 * roots**2 + 0.75 * e3 * roots
    e4 = np.min(ks)
    s_val = 72 + 12 * e3 - 4 * e4
    return e3, e4, s_val

results = []
for e3 in np.linspace(-8, 8, 1000):
    results.append(get_info(e3))

for e3, e4, s_val in results:
    if s_val < -12.000001:
        print(f"e3 = {e3:.4f}, e4 = {e4:.4f}, s_val = {s_val:.4f}")
else:
    print("No value smaller than -12 found.")
